/*
 * PostgreSQL schema for the SIWES Staff Directory.
 *
 * This is the PostgreSQL counterpart of schema.sql (SQLite) and is kept
 * deliberately equivalent:
 *   - plain UNIQUE constraints on the raw columns, matching the SQLite tables;
 *   - integer identity primary keys (GENERATED BY DEFAULT allows the migration
 *     utility to insert the existing explicit ids);
 *   - timestamptz for instants (stored in UTC) and date for due_date;
 *   - application-managed updated_at — no update triggers;
 *   - no case-insensitive unique indexes (look-alike detection stays in the
 *     repositories so both engines behave the same way).
 *
 * It is applied with CREATE ... IF NOT EXISTS so repeated startups are safe.
 */

CREATE TABLE IF NOT EXISTS departments (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        text NOT NULL UNIQUE,
  description text,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS roles (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        text NOT NULL UNIQUE,
  description text,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS staff (
  id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name        text NOT NULL,
  last_name         text NOT NULL,
  email             text NOT NULL UNIQUE,
  phone             text,
  job_title         text,
  department_id     integer,
  role_id           integer,
  location          text,
  avatar_url        text,
  bio               text,
  employment_status text NOT NULL DEFAULT 'Active',
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT staff_department_id_fkey FOREIGN KEY (department_id)
    REFERENCES departments (id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT staff_role_id_fkey FOREIGN KEY (role_id)
    REFERENCES roles (id) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS admins (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username      text NOT NULL UNIQUE,
  email         text NOT NULL UNIQUE,
  password_hash text NOT NULL,
  full_name     text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS admin_sessions (
  id         text PRIMARY KEY,
  admin_id   integer NOT NULL,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT admin_sessions_admin_id_fkey FOREIGN KEY (admin_id)
    REFERENCES admins (id) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS tasks (
  id                  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title               text NOT NULL,
  description         text,
  staff_id            integer NOT NULL,
  priority            text NOT NULL DEFAULT 'Medium',
  status              text NOT NULL DEFAULT 'Pending',
  due_date            date,
  created_by_admin_id integer NOT NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT tasks_staff_id_fkey FOREIGN KEY (staff_id)
    REFERENCES staff (id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT tasks_created_by_admin_id_fkey FOREIGN KEY (created_by_admin_id)
    REFERENCES admins (id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT tasks_priority_check CHECK (priority IN ('Low', 'Medium', 'High', 'Urgent')),
  CONSTRAINT tasks_status_check CHECK (status IN ('Pending', 'In Progress', 'Completed', 'On Hold', 'Cancelled'))
);

CREATE INDEX IF NOT EXISTS idx_staff_department_id ON staff (department_id);
CREATE INDEX IF NOT EXISTS idx_staff_role_id ON staff (role_id);
CREATE INDEX IF NOT EXISTS idx_staff_employment_status ON staff (employment_status);
CREATE INDEX IF NOT EXISTS idx_staff_last_name ON staff (last_name);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_admin_id ON admin_sessions (admin_id);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_expires_at ON admin_sessions (expires_at);
CREATE INDEX IF NOT EXISTS idx_tasks_staff_id ON tasks (staff_id);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks (status);
CREATE INDEX IF NOT EXISTS idx_tasks_created_by_admin_id ON tasks (created_by_admin_id);
CREATE INDEX IF NOT EXISTS idx_tasks_due_date ON tasks (due_date);
